+import { describe, expect, it } from "vitest";
+import { lineTotal, tierFor } from "../src/pricing/tiers";
+
+describe("bulk tiers", () => {
+  it("gives no tier below 10 units", () => {
+    expect(tierFor(5)).toBeUndefined();
+  });
+
+  it("gives 10 % at 60 units", () => {
+    expect(tierFor(60)?.percent).toBe(10);
+  });
+
+  it("discounts the line total", () => {
+    expect(lineTotal({ sku: "A", qty: 60, unitCents: 100 })).toBe(5400);
+  });
+});

