+// Card authorization through PayCo, with retries (PAY-31).
+import { payco } from "../payments/paycoClient";
+import type { PricedOrder } from "./createOrder";
+
+export interface Authorization {
+  id: string;
+  amountCents: number;
+}
+
+const MAX_ATTEMPTS = 3;
+
+/** Authorizes the order total. Retries on network errors and 5xx. */
+export async function authorize(order: PricedOrder, orderId: string): Promise<Authorization> {
+  let lastError: unknown;
+  for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt++) {
+    try {
+      const res = await payco.post("/v2/authorizations", {
+        amount: order.totalCents,
+        currency: "EUR",
+        reference: orderId,
+      });
+      return { id: res.data.id, amountCents: order.totalCents };
+    } catch (err) {
+      lastError = err;
+      await new Promise((r) => setTimeout(r, 250 * attempt));
+    }
+  }
+  throw lastError;
+}
